    if autonomia <= 0:
        break
    distancia = int(input(f"Digite a distância percorrida na viagem {i+1} (em km): "))
    autonomia -= distancia
    if autonomia <= 100 and autonomia > 0:
        print("Hora de carregar o caminhão!")

