exercises.referenceCode:
temperaturas = []

while True:
    entrada = input("Digite a temperatura (ou 000 para encerrar): ")
    if entrada == "000":
        break
    temperatura = float(entrada)
    temperaturas.append(temperatura)

if temperaturas:
    media = sum(temperaturas) / len(temperaturas)
    limite_superior = media * 1.2
    limite_inferior = media * 0.8

    fora_do_padrao = []
    for temp in temperaturas:
        if temp > limite_superior or temp < limite_inferior:
            fora_do_padrao.append(temp)

    print(f"\nMédia das temperaturas: {media:.2f} °C")
    print(f"Temperaturas fora do padrão: {fora_do_padrao}")
else:
    print("Nenhuma temperatura foi registrada.")

