    limite_inferior = media * 0.8

    fora_do_padrao = []
    for temp in temperaturas:
        if temp > limite_superior or temp < limite_inferior:
            fora_do_padrao.append(temp)

    print(f"\nMédia das temperaturas: {media:.2f} °C")
    print(f"Temperaturas fora do padrão: {fora_do_padrao}")
else:
    print("Nenhuma temperatura foi registrada.")

